package exercise

import (
	"reflect"
	"testing"
	"time"
)

func sameEdges(got, want []int) bool {
	if len(got) == 0 && len(want) == 0 {
		return true
	}
	return reflect.DeepEqual(got, want)
}

func TestBridgesSimpleGraphs(t *testing.T) {
	cases := []struct {
		name  string
		n     int
		edges [][2]int
		want  []int
	}{
		{
			name:  "triangle with a tail",
			n:     5,
			edges: [][2]int{{1, 0}, {0, 2}, {2, 1}, {0, 3}, {3, 4}},
			want:  []int{3, 4},
		},
		{
			name:  "path has every edge",
			n:     4,
			edges: [][2]int{{0, 1}, {1, 2}, {2, 3}},
			want:  []int{0, 1, 2},
		},
		{
			name:  "ring has none",
			n:     4,
			edges: [][2]int{{0, 1}, {1, 2}, {2, 3}, {3, 0}},
			want:  []int{},
		},
		{
			name:  "triangle with a hanging loop and one leaf",
			n:     7,
			edges: [][2]int{{0, 1}, {1, 2}, {2, 0}, {1, 3}, {1, 4}, {1, 6}, {3, 5}, {4, 5}},
			want:  []int{5},
		},
		{
			name:  "no edges",
			n:     3,
			edges: nil,
			want:  []int{},
		},
	}

	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			got := Bridges(c.n, c.edges)
			if !sameEdges(got, c.want) {
				t.Errorf("got %v, want %v", got, c.want)
			}
		})
	}
}

func TestBridgesRepeatedEdges(t *testing.T) {
	cases := []struct {
		name  string
		n     int
		edges [][2]int
		want  []int
	}{
		{
			name:  "two copies of one edge",
			n:     2,
			edges: [][2]int{{0, 1}, {1, 0}},
			want:  []int{},
		},
		{
			name:  "doubled edge at the end of a path",
			n:     3,
			edges: [][2]int{{0, 1}, {1, 2}, {1, 2}},
			want:  []int{0},
		},
		{
			name:  "three copies between a hub and a leaf",
			n:     4,
			edges: [][2]int{{0, 1}, {0, 2}, {0, 3}, {0, 3}, {3, 0}},
			want:  []int{0, 1},
		},
		{
			name:  "edge from a vertex to itself",
			n:     2,
			edges: [][2]int{{0, 0}, {0, 1}, {1, 1}},
			want:  []int{1},
		},
	}

	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			got := Bridges(c.n, c.edges)
			if !sameEdges(got, c.want) {
				t.Errorf("got %v, want %v", got, c.want)
			}
		})
	}
}

func TestBridgesDisconnectedGraph(t *testing.T) {
	// A path, a separate triangle, and a vertex with no edges. Only searching
	// from vertex 0 would never look at the triangle side.
	n := 7
	edges := [][2]int{{4, 5}, {0, 1}, {5, 6}, {6, 4}, {1, 2}}

	got := Bridges(n, edges)
	want := []int{1, 4}
	if !sameEdges(got, want) {
		t.Errorf("got %v, want %v", got, want)
	}
}

func TestBridgesResultIsSortedAscending(t *testing.T) {
	// The edges are listed so the search finds the bridges in the reverse
	// of their positions in the list.
	n := 5
	edges := [][2]int{{3, 4}, {2, 3}, {1, 2}, {0, 1}}

	got := Bridges(n, edges)
	want := []int{0, 1, 2, 3}
	if !sameEdges(got, want) {
		t.Errorf("got %v, want %v", got, want)
	}
}

func TestBridgesHandlesLargeGraph(t *testing.T) {
	// A path of a hundred thousand vertices where every other link is
	// doubled. The single links are bridges and the doubled ones are not.
	// Removing one edge at a time and checking the graph is still connected
	// would walk the whole graph once per edge.
	const n = 100000
	var edges [][2]int
	var want []int
	for u := 0; u+1 < n; u++ {
		if u%2 == 0 {
			want = append(want, len(edges))
			edges = append(edges, [2]int{u, u + 1})
		} else {
			edges = append(edges, [2]int{u, u + 1}, [2]int{u + 1, u})
		}
	}

	const budget = 2 * time.Second
	done := make(chan []int, 1)
	go func() { done <- Bridges(n, edges) }()

	var got []int
	select {
	case got = <-done:
	case <-time.After(budget):
		t.Fatalf("still running after %v on a graph of %d vertices: find every bridge in a single traversal", budget, n)
	}

	if !sameEdges(got, want) {
		if len(got) != len(want) {
			t.Fatalf("got %d bridges, want %d", len(got), len(want))
		}
		t.Fatalf("wrong bridges for the large graph")
	}
}

