package exercise

func Bridges(n int, edges [][2]int) []int {
	type halfEdge struct{ to, id int }
	adj := make([][]halfEdge, n)
	for id, e := range edges {
		adj[e[0]] = append(adj[e[0]], halfEdge{e[1], id})
		adj[e[1]] = append(adj[e[1]], halfEdge{e[0], id})
	}

	disc := make([]int, n)
	low := make([]int, n)
	isBridge := make([]bool, len(edges))
	timer := 0

	var dfs func(u, parentEdge int)
	dfs = func(u, parentEdge int) {
		timer++
		disc[u], low[u] = timer, timer

		for _, e := range adj[u] {
			if e.id == parentEdge {
				continue
			}
			v := e.to
			if disc[v] != 0 {
				low[u] = min(low[u], disc[v])
				continue
			}
			dfs(v, e.id)
			low[u] = min(low[u], low[v])
			if low[v] > disc[u] {
				isBridge[e.id] = true
			}
		}
	}

	for u := 0; u < n; u++ {
		if disc[u] == 0 {
			dfs(u, -1)
		}
	}

	res := []int{}
	for id, b := range isBridge {
		if b {
			res = append(res, id)
		}
	}
	return res
}
